const failed = new Promise((resolve, reject) => {
  reject(new Error("timeout"));
});
failed.then(
  (value) => console.log("value: " + value),
  (error) => console.log("reason: " + error.message)
);

const passed = new Promise((resolve) => resolve("ok"));
passed.catch((error) => console.log("never: " + error.message));
passed.then((value) => console.log("value: " + value));
